-- ----------------------------------------------------------------------------
--  Helper Functions
-- ----------------------------------------------------------------------------

--- Check if an enchantID represents a socketed gem rather than an equipment enchant.
-- In WotLK 3.3.5, gem effects share the SpellItemEnchantment ID space with enchants.
-- @param enchantID number
-- @return boolean
function EllesmereUI.IsGemEnchant(enchantID)
    if not enchantID then return false end
    return GemEnchantToItem[enchantID] ~= nil
end

--- Resolve an enchant ID, spell ID, or item ID to the gem's item ID.
-- @param id number
-- @return number|nil
function EllesmereUI.GetGemItemID(id)
    if not id then return nil end
    local num = tonumber(id)
    if not num or num <= 0 then return nil end
    if GemItems[num] then return num end
    return GemEnchantToItem[num] or GemSpellToItem[num] or nil
end

--- Get metadata for a gem by item ID.
-- @param itemID number
-- @return table|nil
function EllesmereUI.GetGemData(itemID)
    if not itemID then return nil end
    return GemItems[tonumber(itemID)]
end

--- Resolve a glyph name or spell ID to its item ID.
-- @param nameOrSpellID string|number
-- @return number|nil
function EllesmereUI.GetGlyphItemID(nameOrSpellID)
    if not nameOrSpellID then return nil end
    local num = tonumber(nameOrSpellID)
    if num then
        if GlyphItems[num] then return num end
        return GlyphSpellToItem[num] or nil
    end
    if type(nameOrSpellID) == "string" then
        return GlyphNameToItem[nameOrSpellID] or nil
    end
    return nil
end

--- Get metadata for a glyph by item ID.
-- @param itemID number
-- @return table|nil
function EllesmereUI.GetGlyphData(itemID)
    if not itemID then return nil end
    return GlyphItems[tonumber(itemID)]
end

local _localizedCache = {}

--- Returns the localized enchant name for a given enchant ID.
-- @param enchantID number
-- @return string
function EllesmereUI.GetEnchantName(enchantID)
    if not enchantID then return "" end
    enchantID = tonumber(enchantID)
    if not enchantID or enchantID <= 0 then return "" end

    -- Gems are not gear enchants
    if GemEnchantToItem[enchantID] then return "" end

    local raw = EnchantNames[enchantID]
    if not raw or raw == "" then return "" end

    -- Check active client locale
    local locale = (GetLocale and GetLocale()) or "enUS"
    if EllesmereUIDB and EllesmereUIDB.localeOverride and EllesmereUIDB.localeOverride ~= "" then
        locale = EllesmereUIDB.localeOverride
    end

    local cacheKey = locale .. ":" .. enchantID
    local cached = _localizedCache[cacheKey]
    if cached ~= nil then return cached end

    if locale == "enUS" or locale == "enGB" then
        _localizedCache[cacheKey] = raw
        return raw
    end

    -- 1. Check EllesmereUI.L full-string translation
    if EllesmereUI.L then
        local tr = EllesmereUI.L(raw)
        if tr and tr ~= raw then
            _localizedCache[cacheKey] = tr
            return tr
        end
    end

    -- 2. Check NamedEnchants dictionary
    local namedMap = NamedEnchants[locale]
    if namedMap and namedMap[raw] then
        local tr = namedMap[raw]
        _localizedCache[cacheKey] = tr
        return tr
    end

    -- 3. Tokenized stat translation
    local statMap = StatTranslations[locale]
    if statMap then
        local translated = raw
        -- Sort phrases by descending length so multi-word tokens match first
        -- e.g. "to All Stats", "All Stats", "Defense Rating", "Fishing Skill"
        local multiTokens = {
            "to All Stats", "All Stats", "Defense Rating", "Fishing Skill",
            "Fishing Lure", "Counterweight", "Spell Penetration", "All Resistances",
            "Fire Resistance", "Frost Resistance", "Shadow Resistance",
            "Nature Resistance", "Arcane Resistance", "Armor Pen",
        }
        for _, token in ipairs(multiTokens) do
            if statMap[token] and translated:find(token, 1, true) then
                translated = translated:gsub(token:gsub("([%(%)%.%[%]%^%$%*%+%-%?%%])", "%%%1"), statMap[token])
            end
        end

        -- Word tokens (matching whole words or words adjacent to numbers/punct)
        local singleTokens = {
            "SP", "AP", "Crit", "Haste", "Hit", "Stamina", "Strength", "Agility",
            "Intellect", "Spirit", "Dodge", "Parry", "Block", "Resilience",
            "Armor", "Mana", "Health", "Damage", "MP5", "HP5", "Defense",
            "Scope", "Reinforced", "Sharpened", "Weighted",
        }
        for _, token in ipairs(singleTokens) do
            if statMap[token] then
                -- Match whole word
                translated = translated:gsub("(%f[%a])" .. token .. "(%f[%A])", "%1" .. statMap[token] .. "%2")
            end
        end

        if statMap["&"] then
            translated = translated:gsub("%s*&%s*", " " .. statMap["&"] .. " ")
        end

        _localizedCache[cacheKey] = translated
        return translated
    end

    _localizedCache[cacheKey] = raw
    return raw
end

